 "content": "def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    common = Counter(x for row in grid for x in row).most_common(1)[0][0]
    candidates = []
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and row[0] != common:
            candidates.append(("h", r))
    for c in range(w):
        vals = {grid[r][c] for r in range(h)}
        if len(vals) == 1 and grid[0][c] != common:
            candidates.append(("v", c))
    orientation, cut = candidates[0]

    if orientation == "v":
        panels = ([row[:cut] for row in grid], [row[cut + 1:] for row in grid])
    else:
        panels = (grid[:cut], grid[cut + 1:])

    a, b = panels
    base_colors = set(x for row in a for x in row) & set(x for row in b for x in row)
    base = next(iter(base_colors))
    bg_a = Counter(x for row in a for x in row).most_common(1)[0][0]
    bg_b = Counter(x for row in b for x in row).most_common(1)[0][0]
    out_h, out_w = min(len(a), len(b)), min(len(a[0]), len(b[0]))
    return [[3 if a[r][c] != bg_a and b[r][c] != bg_b else base
             for c in range(out_w)] for r in range(out_h)]
